from fractions import Fraction as F
toks = ["24", "/", "3", "-", "4", "*", "2", "+", "6", "*", "5", "+", "12"]
def value(t):
    return eval("".join("F(%s)" % x if x.isdigit() else x for x in t))
def swap(t, a, b):
    i, j = t.index(a), t.index(b)
    t = t[:]
    t[i], t[j] = t[j], t[i]
    return t
opts = {"A": ("4", "3"), "B": ("5", "4"), "C": ("3", "2"), "D": ("24", "12")}
match = [k for k, (a, b) in opts.items() if value(swap(toks, a, b)) == 50]
assert len(match) == 1
print(f"ANSWER={match[0]}")

