from fractions import Fraction as F
s, m = F(7, 10), F(7, 20)          # square side and radius midpoint (radius 1), centre at (0, 0)
def seg(a, b):
    return tuple(sorted([a, b]))
square = {seg((0, 0), (s, 0)), seg((s, 0), (s, s)), seg((s, s), (0, s)), seg((0, s), (0, 0))}
chord = seg((1, 0), (0, 1))
# bottom-left quadrant as drawn (x < 0), y measured downwards
bottom_left = {seg((0, 0), (-s, 0)), seg((-s, 0), (-s, s)), seg((-s, s), (0, s)), seg((0, s), (0, 0)),
               seg((-1, 0), (0, 1)), seg((0, 0), (-s, s)), seg((-m, 0), (-s, s))}
mirror = {seg((-a[0], a[1]), (-b[0], b[1])) for a, b in bottom_left}
half = F(1, 2)
opts = {
    "A": square | {chord, seg((0, 0), (s, s)), seg((m, 0), (s, s))},
    "B": square | {chord, seg((0, 0), (half, half)), seg((0, s), (F(3, 10), F(3, 10)))},
    "C": square | {chord, seg((0, 0), (half, half)), seg((m, 0), (0, s))},
    "D": (square - {seg((s, 0), (s, s))}) | {seg((s, F(9, 20)), (s, s)), chord, seg((0, 0), (s, s)), seg((m, 0), (0, s))},
}
match = [k for k, v in opts.items() if v == mirror]
assert len(match) == 1
print(f"ANSWER={match[0]}")

