pattern = "P_AA__ZA_V__A__"
opts = {"A": "ZVPAPZAV", "B": "ZPVVAPVZ", "C": "VZAAPVPZ", "D": "VPZZPVAP"}
def fill(p, f):
    it = iter(f)
    return "".join(next(it) if c == "_" else c for c in p)
def periodic(s, n):
    return all(s[i] == s[i % n] for i in range(len(s)))
