code = {"/": "mother", "x": "brother", "-": "sister", "+": "son"}
expr = [("P", "/", "Q"), ("Q", "x", "R"), ("R", "-", "M"), ("M", "+", "T")]
mother, parent_of, siblings = {}, {}, []
for a, op, b in expr:
    r = code[op]
    if r == "mother":
        mother[b] = a
    elif r in ("brother", "sister"):
        siblings.append((a, b))
    elif r == "son":
        parent_of.setdefault(a, set()).add(b)
changed = True
while changed:                      # siblings share a mother
    changed = False
    for a, b in siblings:
        for x, y in ((a, b), (b, a)):
            if x in mother and y not in mother:
                mother[y] = mother[x]
                changed = True
child = "M"
other = parent_of[child] - {mother[child]}
assert other == {"T"}
# the child's mother is P, so T (the other parent) is the father, and the father of P's child is P's spouse
t_gender = "m" if mother[child] == "P" else "?"
spouse_of_p = {"m": "Husband", "f": "Wife"}[t_gender]
result = spouse_of_p
opts = {"A": "Brother", "B": "Husband", "C": "Father", "D": "Son"}
match = [k for k, v in opts.items() if v == result]
assert len(match) == 1
print(f"ANSWER={match[0]}")
